inputs = ['cv', 'gzgkh', 'vb', 'eg', 'hejyuh']
outputs = ['cdv', 'gzgkh', 'dvb', 'eg', 'hejefduh']

# Only consider the changed pairs
changed_pairs = []
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        changed_pairs.append((i, inp, outp))

print("Changed pairs:")
for idx, inp, outp in changed_pairs:
    print(f"  {idx}: '{inp}' -> '{outp}'")

# Let's look at the minimal edits for each changed pair
def find_minimal_edit(s_in, s_out):
    """Find the minimal edit operation"""
    # Simple implementation for our purposes
    if len(s_in) < len(s_out):
        # Insertion
        for i in range(len(s_in)):
            if s_in[i:] == s_out[i+1:]:
                return (s_in[i:], s_out[i:i+1], i)
        # Special case: insertion at beginning
        if s_in == s_out[1:]:
            return ("", s_out[0], 0)
    elif len(s_in) > len(s_out):
        # Deletion
        for i in range(len(s_out)):
            if s_out[i:] == s_in[i+1:]:
                return (s_in[i:i+1], "", i)
    else:
        # Substitution
        for i in range(len(s_in)):
            if s_in[:i] == s_out[:i] and s_in[i+1:] == s_out[i+1:]:
                return (s_in[i], s_out[i], i)
    return (s_in, s_out, 0)

print("\nMinimal edits:")
for idx, inp, outp in changed_pairs:
    old_sub, new_sub, pos = find_minimal_edit(inp, outp)
    print(f"  {idx}: '{inp}' -> '{outp}': change '{old_sub}' to '{new_sub}' at position {pos}")

